// Quotas in KiB.
const PLANS = {
  free: { quotaKiB: 524288 },
  team: { quotaKiB: 209715200 },
  archive: { quotaKiB: 2147483648 },
};

function quotaBytes(plan) {
  const entry = PLANS[plan];
  if (!entry) throw new Error('unknown plan: ' + plan);
  return entry.quotaKiB << 10;
}

module.exports = { PLANS, quotaBytes };
const SHARDS = 16;

function shardFor(name) {
  let h = 0;
  for (const ch of name) h = (h * 31 + ch.charCodeAt(0)) % SHARDS;
  return h;
}

module.exports = { shardFor, SHARDS };
const { usedBytes } = require('./usage');
const { shardFor } = require('./shard');
const { quotaBytes } = require('./plans');

function acceptUpload(account, file) {
  const after = usedBytes(account.files) + file.size;
  if (after > quotaBytes(account.plan)) {
    return { ok: false, reason: 'over quota' };
  }
  account.files.push(file);
  return { ok: true, shard: shardFor(file.name) };
}

module.exports = { acceptUpload };
const BLOCK = 4096;

function usedBytes(files) {
  return files.reduce((n, f) => n + Math.ceil(f.size / BLOCK) * BLOCK, 0);
}

module.exports = { usedBytes, BLOCK };
